mapper.select:
SELECT id, gateway_id, gateway_name, gateway_desc, version, status, auth, create_time, update_time
FROM mcp_gateway
WHERE id = #{id}

SELECT id, gateway_id, gateway_name, gateway_desc, version, status, auth
FROM mcp_gateway
WHERE gateway_id = #{gatewayId}

SELECT id, gateway_id, gateway_name, gateway_desc, version, status, auth, create_time, update_time FROM mcp_gateway
AND gateway_id LIKE CONCAT('%', #{gatewayId}, '%') AND gateway_name LIKE CONCAT('%', #{gatewayName}, '%')
ORDER BY id DESC LIMIT #{limitStart}, #{limitCount}
